sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  var c = this;

  c.selectedYear = "";

  function atualizarIndicador() {
    c.server.get({ selectedYear: c.selectedYear }).then(function(response) {
      c.data = response.data;
      // console.log("Indicador Investimento atualizado:", c.selectedYear, c.data);
    });
  }

  // Escuta o evento de filtro de ano
  $rootScope.$on('anoSelecionado', function(event, ano) {
    c.selectedYear = ano;
    atualizarIndicador();
  });

  // Carregamento inicial
  atualizarIndicador();
}

sp_widget.css:
.financial-widget {
  font-family: Roboto;
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  margin-top: 4rem;
}

.indicator-block {
  text-align: center;
  padding: 0;
}

.indicator-header {
  background-color: #EBEDF1;
  color: #021770;
  font-weight: 400;
  padding: 8px 10px;
  font-size: 14px;
  border-bottom: 1px solid #C7C7C7;
}

.indicator-value {
  color: #021770;
  font-size: 32px;
  font-weight: 400;
  padding: 10px 10px 15px;
}

sp_widget.script:
(function() {
    input = input || {};
    var table = 'x_sded9_portal_t_0_investimento';
    var selectedYear = input.selectedYear || "";

    // 1. Busca o ano mais recente se nenhum for selecionado
    if (!selectedYear) {
        var g = new GlideRecord(table);
        g.orderByDesc('u_ano');
        g.setLimit(1);
        g.query();
        if (g.next())
            selectedYear = g.getValue('u_ano');
    }

    data.selectedYear = selectedYear;

    // Valor padrão com ponto
    data.indicator = {
        value: 'R$ 0.00', 
        label: 'Investimento: ' + (selectedYear ? selectedYear : 'N/A')
    };

    // 2. Busca o dado na tabela
    var gr = new GlideRecord(table);

    if (selectedYear) {
        gr.addQuery('u_ano', selectedYear);
    }

    gr.orderByDesc('sys_created_on');
    gr.setLimit(1);
    gr.query();

    if (gr.next()) {
        var anoReal = gr.getValue('u_ano');
        var valorBruto = gr.getValue('investimento_liquidado') || '0'; 

        // Chama a função de formatação corrigida
        var valorFormatado = formatarMoedaAbreviada(valorBruto);

        data.indicator.value = valorFormatado; 
        data.indicator.label = 'Investimento ' + anoReal + ':';
        data.selectedYear = anoReal;
    }

    // --- Função de Formatação Ajustada (Sem Arredondamento) ---
    function formatarMoedaAbreviada(valorStr) {
        if (!valorStr) return "R$ 0.00";

        // Converte string BR para Float JS
        var valor = parseFloat(valorStr.toString().replace(/\./g, '').replace(',', '.'));

        if (isNaN(valor)) return "R$ 0.00";

        var divisor = 1;
        var sufixo = "";
        var absValor = Math.abs(valor);

        // Define a escala (Bi, Milhões, Mil)
        if (absValor >= 1000000000) {
            divisor = 1000000000;
            sufixo = ' Bi';
        } else if (absValor >= 1000000) {
            divisor = 1000000;
            sufixo = ' Milhões';
        } else if (absValor >= 1000) {
            divisor = 1000;
            sufixo = ' Mil';
        }

        // Realiza a divisão
        var valorDividido = valor / divisor;

        // Lógica de TRUNCAMENTO (Math.floor)
        // Multiplica por 100, remove decimais extras, divide por 100
        var valorTruncado = Math.floor(Math.abs(valorDividido) * 100) / 100;

        // Restaura o sinal negativo se necessário
        if (valor < 0) {
            valorTruncado = valorTruncado * -1;
        }

        // Retorna formatado sempre com 2 casas
        return 'R$ ' + valorTruncado.toFixed(2) + sufixo;
    }

})();
